import { motion } from 'framer-motion';

import { Tag } from '../../hooks/useTags';
import { normalizeTag } from '../../utils/tagUtils';

interface TagListProps {
  tags: Tag[];
  selectedTags: string[];
  onTagSelect: (tagId: string) => void;
}

export default function TagList({ tags, selectedTags, onTagSelect }: TagListProps) {
  return (
    <div
      className="flex flex-wrap gap-2"
      role="listbox"
      aria-label="Available tags"
      aria-multiselectable="true"
    >
      {tags.map(tag => {
        const normalizedTag = normalizeTag(tag.name);
        const isSelected = selectedTags.includes(normalizedTag);

        return (
          <motion.button
            key={tag.id}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => onTagSelect(normalizedTag)}
            className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors focus:outline-hidden focus-visible:ring-2 focus-visible:ring-primary ${
              isSelected
                ? 'bg-primary text-white dark:text-white font-semibold'
                : 'bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light hover:bg-primary/20 dark:hover:bg-primary/30'
            }`}
            role="option"
            aria-selected={isSelected}
          >
            {tag.name}
          </motion.button>
        );
      })}
    </div>
  );
}
