import { supabase } from '../lib/supabase/client';

import { useSupabaseQuery } from './useSupabaseQuery';

export interface Tag {
  id: string;
  name: string;
  category?: string;
  color?: string;
}

export function useTags() {
  const {
    data: tags,
    isLoading,
    error,
    refetch,
  } = useSupabaseQuery(
    async () => {
      const { data, error } = await supabase.from('tags').select('*').order('name');

      if (error) throw error;

      // Deduplicate tags by name
      const uniqueTags = (data || []).reduce((acc: Tag[], tag) => {
        if (!acc.find(t => t.name === tag.name)) {
          acc.push(tag as Tag);
        }
        return acc;
      }, []);

      return uniqueTags;
    },
    { initialData: [] as Tag[] }
  );

  return { tags, isLoading, error, refetch };
}
