import React, { Suspense, useState } from 'react';

import { AwardGridSkeleton } from '../components/common/AwardSkeleton';
import { CardGridSkeleton } from '../components/common/CardSkeleton';
import ErrorBoundary from '../components/common/ErrorBoundary';
import { HeroSkeleton } from '../components/common/HeroSkeleton';
import HomeFilter from '../components/common/HomeFilter';
import SEO from '../components/SEO';
import { useFilteredContent } from '../hooks/useFilteredContent';
import { useTags } from '../hooks/useTags';

// Lazy load components with error boundaries
const Skills = React.lazy(() => import('../components/Skills/index'));
const Projects = React.lazy(() => import('../components/Projects/index'));
const Articles = React.lazy(() => import('../components/Articles/index'));
const Awards = React.lazy(() => import('../components/Awards/index'));

export default function HomePage() {
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const { tags, isLoading: tagsLoading } = useTags();
  const { articles, projects, isLoading: contentLoading } = useFilteredContent(selectedTags);

  // Show skeleton layout while initial content loads
  if (contentLoading && !articles && !projects) {
    return (
      <div className="min-h-screen pt-24 container mx-auto px-6">
        <HeroSkeleton />
        <CardGridSkeleton />
        <div className="mt-16">
          <CardGridSkeleton />
        </div>
      </div>
    );
  }

  const handleTagSelect = (tagId: string) => {
    setSelectedTags(prev => {
      const isSelected = prev.includes(tagId);
      if (isSelected) {
        return prev.filter(t => t !== tagId);
      }
      return [...prev, tagId];
    });
  };

  const handleClearFilters = () => {
    setSelectedTags([]);
  };

  return (
    <main>
      <SEO
        title="REWI.RE YOUR EXPERIENCES"
        description="REWI.RE fuses strategic insight, cutting-edge technology and human-centered storytelling to create experiences that shatter conventions and redefine what's possible."
        path="/"
        type="website"
      />

      <ErrorBoundary>
        <Suspense fallback={<HeroSkeleton />}>
          <Skills />
        </Suspense>
      </ErrorBoundary>

      <div className="container mx-auto px-6 py-8">
        {!tagsLoading && (
          <HomeFilter
            tags={tags || []}
            selectedTags={selectedTags}
            onTagSelect={handleTagSelect}
            onClearFilters={handleClearFilters}
            articleCount={articles?.length || 0}
            projectCount={projects?.length || 0}
          />
        )}
      </div>

      <ErrorBoundary>
        <Suspense fallback={<CardGridSkeleton />}>
          <Projects
            initialProjects={projects || []}
            selectedTags={selectedTags}
            isLoading={contentLoading}
          />
        </Suspense>
      </ErrorBoundary>

      <ErrorBoundary>
        <Suspense fallback={<CardGridSkeleton />}>
          <Articles
            initialArticles={articles || []}
            selectedTags={selectedTags}
            isLoading={contentLoading}
          />
        </Suspense>
      </ErrorBoundary>

      <ErrorBoundary>
        <Suspense fallback={<AwardGridSkeleton />}>
          <Awards />
        </Suspense>
      </ErrorBoundary>
    </main>
  );
}
